struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float hash21(float2 p)
{
    return frac(sin(dot(p, float2(41.1, 289.7))) * 45758.5453);
}

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.0005;
    float scale = 10.0;
    float2 uv = i.uv * scale;
    float2 id = floor(uv);
    float2 gv = frac(uv);
    float rnd = hash21(id + floor(t) * 0.01);
    if (rnd > 0.5) gv.x = 1.0 - gv.x;
    float d1 = length(gv - float2(0, 0)) - 0.5;
    float d2 = length(gv - float2(1, 1)) - 0.5;
    float d = min(abs(d1), abs(d2));
    float lineWidth = 0.08;
    float line = smoothstep(lineWidth, lineWidth - 0.02, d);
    float3 bg = float3(0.95, 0.92, 0.88);
    float3 fg = 0.5 + 0.5 * sin(float3(0, 2, 4) + id.x * 0.5 + id.y * 0.3 + t * 2.0);
    float3 col = lerp(bg, fg, line);
    return float4(col, 1.0);
}
